/* Engine rows for fastdl.c, generated from the reverse engineering data of the 1.0 / 1.1 surveys.
 * test/rows.sh checks every row against the engine DLLs (signatures, relocations, data, exports).
 * Row format: engine_t in engine.h. Module rows (module != NULL): every address is an RVA, the image is
 * relocated at run time. Blob rows (module == NULL): absolute VAs at the fixed blob base. */

/* ---- HL 1.0 family: 1.0.0.5 - 1.0.1.6 (protocols 35-40), hw.dll and sw.dll ---------------------------------
 * PE images with .reloc and preferred base 0x10000000. hl.exe statically imports WONAuth/WONCrypt, which
 * also want that base, so the engine always runs relocated. No base relocation falls inside any signature.
 *
 * site                    signature                                         builds   how found
 * CL_CheckOrDownloadFile  81 ec b0 04 00 00 53 56 57 33 db 8b b4 24 c0 04   all 16   function with the reference
 *                         (prologue 6: sub esp,0x4b0)                                to "Refusing to download a path
 *                                                                                    with '..'\n"
 * COM_FileSize            8b 4c 24 04 83 ec 04 8d 44 24 00 56               1.0.0.9+ COM_FindFile(0,0,name,0,&f) +
 *                                                                                    fclose, unique 29-byte pattern
 * COM_FOpenFile           8b 44 24 08 8b 4c 24 04 50 6a 00 51               1.0.0.5- wrapper of the 3-arg COM_FindFile
 *                                                                           1.0.0.8  that CL_CheckOrDownloadFile calls
 * fclose (engine CRT)     56 57 bf ff ff ff ff 8b 74 24 0c f6               all 16   call after the COM_FindFile
 *                                                                                    test in CL_CheckOrDownloadFile
 * Con_Printf              b8 00 10 00 00 e8 + export "Con_Printf"           all 16   export (also the refusal print)
 * Cmd_Argv                export "Cmd_Argv"                                 all 16   export
 * data, no signature: cl.serverinfo = destination of the strcpy in the "fullserverinfo" handler (1.0.0.9+,
 * cl + 0x208d8, inside the CL_ClearState memset); cmd_functions = list head in Cmd_AddCommand; net_from = the
 * 5 dwords given to NET_AdrToString for "Connection accepted by %s"; com_gamedir = first %s of the "%s/%s" path
 * in CL_ParseDownload; cl_allowdownload = data dword pointing at its name, value at +20 (1.0.0.5-1.0.0.8, older
 * cvar_t) or +12, both read as float in CL_CheckOrDownloadFile.
 * All 16: sprintf(local[64], name) and 64-byte cls.downloadname/downloadtempname -> name_max 59, no %, ASCII.
 * 1.0.0.5-1.0.0.8 have no "fullserverinfo" command: the plugin links its own (SI_PLUGIN_CMD). */
#define SIG_COD10   0x81,0xec,0xb0,0x04,0x00,0x00,0x53,0x56,0x57,0x33,0xdb,0x8b,0xb4,0x24,0xc0,0x04
#define SIG_FSIZE10 0x8b,0x4c,0x24,0x04,0x83,0xec,0x04,0x8d,0x44,0x24,0x00,0x56
#define SIG_FOPEN10 0x8b,0x44,0x24,0x08,0x8b,0x4c,0x24,0x04,0x50,0x6a,0x00,0x51
#define SIG_FCLOSE10 0x56,0x57,0xbf,0xff,0xff,0xff,0xff,0x8b,0x74,0x24,0x0c,0xf6
#define SIG_CONP10  0xb8,0x00,0x10,0x00,0x00,0xe8
#define F10 (ENG_NAME_IS_FORMAT | ENG_NAME_ASCII | ENG_EXPORTS)
/* ROW10_A: 1.0.0.5-1.0.0.8 (COM_FOpenFile + fclose, own fullserverinfo); ROW10_B: 1.0.0.9+ (COM_FileSize, cl.serverinfo) */
#define ROW10_A(nm, mod, st, sz, cod, fo, fc, cp, cmdf, nf, gd, cv) \
	{ nm, mod, st, sz, API_CHECKORDOWNLOAD_NAME, FS_FOPEN_FCLOSE, SI_PLUGIN_CMD, 20, \
	  { cod, { SIG_COD10 }, 16, 6 }, { fo, { SIG_FOPEN10 }, 12, 0 }, { fc, { SIG_FCLOSE10 }, 12, 0 }, \
	  { cp, { SIG_CONP10 }, 6, 0 }, { 0 }, { 0 }, 0, cmdf, nf, gd, cv, 59, F10, { 0 }, 0 }
#define ROW10_B(nm, mod, st, sz, cod, fs, cp, si, gd, cv) \
	{ nm, mod, st, sz, API_CHECKORDOWNLOAD_NAME, FS_SIZE, SI_ENGINE, 12, \
	  { cod, { SIG_COD10 }, 16, 6 }, { fs, { SIG_FSIZE10 }, 12, 0 }, { 0 }, \
	  { cp, { SIG_CONP10 }, 6, 0 }, { 0 }, { 0 }, si, 0, 0, gd, cv, 59, F10, { 0 }, 0 }

