#define PUSH_L0 { 0x30c4, 0x2fbc, 0x08, 0x10, 0x590 }
#define PUSH_L1 { 0x1ffc, 0x1ff4, 0x0c, 0x14, 0 }
#define PUSH_L2 { 0x1fe0, 0x1fd8, 0x10, 0x18, 0 }
